import type {
	BodyMeasurement,
	PutBodyMeasurement,
} from "@hevy-mcp/hevy-client/types";
import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";
import { createBodyMeasurementsUpdateOperation } from "./body-measurements.js";

// OpenAPI PUT /v1/body_measurements/{date}: "All fields are overwritten;
// omitted fields are set to null." The update-body-measurement MCP tool
// promises "Omitted fields remain unchanged". The operation therefore must
// send the stored values for every field the caller did not change.
describe("bodyMeasurements.update bughunt", () => {
	it("preserves stored fields the caller omitted on the full-overwrite PUT", async () => {
		const existing: BodyMeasurement = {
			date: "2025-01-01",
			weight_kg: 80,
			waist: 82,
			fat_percent: 18,
		};
		const getBodyMeasurement = vi.fn(() => Effect.succeed(existing));
		const updateBodyMeasurement = vi.fn(
			(_date: string, data: PutBodyMeasurement) => Effect.succeed(data),
		);
		const adapter = { getBodyMeasurement, updateBodyMeasurement };
		const operation = createBodyMeasurementsUpdateOperation(adapter);

		await Effect.runPromise(
			operation.effect({ date: "2025-01-01", weight_kg: 81 }),
		);

		const sentBody = updateBodyMeasurement.mock.calls[0]?.[1];
		expect(sentBody).toEqual({ weight_kg: 81, waist: 82, fat_percent: 18 });
	});
});
import { describe, expect, it } from "vitest";
import {
	replaceWorkoutInputSchema,
	replaceWorkoutExercisesInputSchema,
	routineExerciseSchema,
	routineSetSchema,
	workoutSetSchema,
} from "./schemas.js";
import { buildRoutinePayload } from "./mutation-semantics.js";

describe("schemas bughunt", () => {
	// Hevy marks routine set weight/distance/duration/custom_metric nullable;
	// null means "not tracked". Workout sets keep null; routine sets must too.
	it("keeps an explicit null routine set weight instead of coercing it to 0 kg", () => {
		const workoutSet = workoutSetSchema.parse({ weight_kg: null, reps: 10 });
		const routineSet = routineSetSchema.parse({
			weight_kg: null,
			reps: 10,
			distance_meters: null,
			duration_seconds: null,
			custom_metric: null,
		});
		expect(workoutSet.weight_kg).toBeNull();
		expect({
			weight_kg: routineSet.weight_kg ?? null,
			distance_meters: routineSet.distance_meters ?? null,
			duration_seconds: routineSet.duration_seconds ?? null,
			custom_metric: routineSet.custom_metric ?? null,
		}).toEqual({
			weight_kg: null,
			distance_meters: null,
			duration_seconds: null,
			custom_metric: null,
		});
	});

	it("does not send weight_kg 0 to Hevy for a routine set given weight_kg null", () => {
		const exercise = routineExerciseSchema.parse({
			exercise_template_id: "ABC",
			sets: [{ weight_kg: null, reps: 10 }],
		});
		const { payload } = buildRoutinePayload(
			{ title: "Push", exercises: [exercise] },
			"update",
		);
		expect(payload.exercises?.[0]?.sets?.[0]?.weight_kg).toBeNull();
	});

	// WORKOUT_PUT_REQUIRES_IS_PRIVATE: GET never returns privacy, so a PUT must
	// state it explicitly. replaceWorkoutExercisesInputSchema requires it;
	// replaceWorkoutInputSchema (CLI `workouts update`) silently defaults false,
	// which flips a private workout to public.
	it("requires is_private on the full workout replacement PUT schema", () => {
		const body = {
			workout_id: "w1",
			workout: {
				title: "Legs",
				start_time: "2025-01-01T10:00:00Z",
				end_time: "2025-01-01T11:00:00Z",
				exercises: [],
			},
		};
		expect(
			replaceWorkoutExercisesInputSchema.safeParse({
				workout_id: "w1",
				workout: { exercises: [] },
			}).success,
		).toBe(false);
		const parsed = replaceWorkoutInputSchema.safeParse(body);
		expect(parsed.success ? parsed.data.workout.is_private : "rejected").toBe(
			"rejected",
		);
	});
});
import type { Workout } from "@hevy-mcp/hevy-client/types";
import { DateTime, Effect } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it } from "vitest";
import { createBodyMeasurementsListOperation } from "./body-measurements.js";
import { createWorkoutsListOperation } from "./workouts.js";
import { createWorkflowsTrainingSummaryOperation } from "./workflows.js";

const FIXED_NOW = DateTime.toEpochMillis(
	DateTime.makeUnsafe("2026-07-16T12:00:00Z"),
);

function runAtFixedTime<A, E>(program: Effect.Effect<A, E>): Promise<A> {
	return Effect.runPromise(
		Effect.provide(
			Effect.gen(function* () {
				yield* TestClock.setTime(FIXED_NOW);
				return yield* program;
			}),
			TestClock.layer(),
		),
	);
}

// get-training-summary: "Summarizes ... for the last 1–12 weeks". One week is
// seven calendar days; the inclusive [start_date, end_date] window is eight.
describe("workflows.trainingSummary bughunt", () => {
	it("covers exactly 7 calendar days for weeks: 1", async () => {
		const eightDaysAgo: Workout = {
			id: "w-8d",
			start_time: "2026-07-09T12:00:00Z",
			end_time: "2026-07-09T13:00:00Z",
			exercises: [],
		};
		const workouts = createWorkoutsListOperation({
			getWorkouts: () =>
				Effect.succeed({ page: 1, page_count: 1, workouts: [eightDaysAgo] }),
		});
		const bodyMeasurements = createBodyMeasurementsListOperation({
			getBodyMeasurements: () =>
				Effect.succeed({ page: 1, page_count: 1, body_measurements: [] }),
		});
		const operation = createWorkflowsTrainingSummaryOperation({
			workouts,
			bodyMeasurements,
		});

		const result = await runAtFixedTime(operation.effect({ weeks: 1 }));
		const days =
			(Date.parse(`${result.period.end_date}T00:00:00Z`) -
				Date.parse(`${result.period.start_date}T00:00:00Z`)) /
				86_400_000 +
			1;
		expect({ days, count: result.workouts.count }).toEqual({
			days: 7,
			count: 0,
		});
	});
});
