		const value = fields[key];
		if (value != null) {
			payload[key] = value;
		}
	}
	return payload;
}

export type MeasurementMergeResult = {
	readonly payload: MeasurementPayload;
	readonly measurement: BodyMeasurement;
};

/**
 * Merge an update with an existing measurement. Null changes are ignored,
 * because the Hevy API rejects null numeric fields and has no clear operation.
 */
export function mergeMeasurementPayload(
	existing: BodyMeasurement,
	changes: MeasurementFields,
): MeasurementMergeResult {
	const payload: MeasurementPayload = {};
	const measurement = { ...existing };

	for (const key of measurementKeys) {
		const changed = changes[key];
		if (changed !== undefined) {
			if (changed !== null) {
				measurement[key] = changed;
				payload[key] = changed;
			}
			continue;
		}
		const existingValue = existing[key];
		if (existingValue != null) payload[key] = existingValue;
	}

	return { payload, measurement };
}
	}
	return result;
}

function updateMeasurement(
	operations: HevyOperations,
	date: string,
	input: CliMeasurementUpdateInput,
	execution: CommandContext["execution"],
) {
	const getOperation = requireOperation(
		operations.bodyMeasurements?.get,
		"bodyMeasurements.get",
	);
	const updateOperation = requireOperation(
		operations.bodyMeasurements?.update,
		"bodyMeasurements.update",
	);
	const effect = Effect.fn("cli.measurements.update")(function* () {
		const existing = yield* getOperation.effect({ date }, execution);
		const parsed = existingBodyMeasurementSchema.safeParse(
			existing.bodyMeasurement,
		);
		if (!parsed.success || parsed.data.date !== date) {
			return yield* Effect.fail(
				new ApiResponseError("The API returned an invalid body measurement"),
			);
		}
		const { measurement } = mergeMeasurementPayload(parsed.data, input);
		yield* updateOperation.effect(measurement, execution);
		return measurement;
	});
	return collapse(effect());
}

async function executeMeasurementList({
	args,
	operations,
	execution,
}: CommandContext): Promise<unknown> {
	const { page, pageSize } = parsePagination(
		args,
		getV1BodyMeasurementsQueryParamsSchema,
	);
	const result = await runOperation(
		operations.bodyMeasurements?.list,
		"bodyMeasurements.list",
		{ page, pageSize },
		execution,
	);
	if (result.expected404Outcome === "end_of_list")
		return pageEnvelope(
			{ page: result.page, page_count: result.pageCount ?? 0 },
			"body_measurements",
			result.items,
		);
	if (result.pageCount === undefined)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	return list(
		{
			page: result.page,
			page_count: result.pageCount,
			body_measurements: result.items,
		},
		"body_measurements",
		"body_measurements",
		page,
	);
}

async function executeMeasurementGet({
		createLazyRequestEffectClient("idempotent-write");
	const nonIdempotentWriteClient = createLazyRequestEffectClient(
		"non-idempotent-write",
	);
	const workoutsList = createWorkoutsListOperation(readClient);
	const bodyMeasurementsList = createBodyMeasurementsListOperation(readClient);
	return {
		routines: {
			create: createRoutinesCreateOperation(nonIdempotentWriteClient),
			get: createRoutinesGetOperation(readClient),
			list: createRoutinesListOperation(readClient),
			search: createRoutinesSearchOperation(readClient),
			update: createRoutinesUpdateOperation(idempotentWriteClient),
		},
		workouts: {
			count: createWorkoutsCountOperation(readClient),
			create: createWorkoutsCreateOperation(nonIdempotentWriteClient),
			events: createWorkoutsEventsOperation(readClient),
			get: createWorkoutsGetOperation(readClient),
			list: workoutsList,
			replaceExercises: createWorkoutsReplaceExercisesOperation(
				idempotentWriteClient,
			),
			update: createWorkoutsUpdateOperation(idempotentWriteClient),
		},
		bodyMeasurements: {
			create: createBodyMeasurementsCreateOperation(nonIdempotentWriteClient),
			get: createBodyMeasurementsGetOperation(readClient),
			list: bodyMeasurementsList,
			update: createBodyMeasurementsUpdateOperation(idempotentWriteClient),
		},
		folders: {
			create: createFoldersCreateOperation(nonIdempotentWriteClient),
			get: createFoldersGetOperation(readClient),
			listAll: createFoldersListAllOperation(readClient),
		},
		templates: {
			create: createTemplatesCreateOperation(nonIdempotentWriteClient),
			get: createTemplatesGetOperation(readClient),
			history: createTemplatesHistoryOperation(readClient),
			listAll: createTemplatesListAllOperation(readClient),
	"WorkoutPrivacyError",
	{
		message: Schema.String,
	},
) {}

export class WorkoutPayloadError extends Schema.TaggedError<WorkoutPayloadError>()(
	"WorkoutPayloadError",
	{
		message: Schema.String,
	},
) {}

export class EmptyMeasurementUpdateError extends Schema.TaggedError<EmptyMeasurementUpdateError>()(
	"EmptyMeasurementUpdateError",
	{
		message: Schema.String,
	},
) {}

export class TrainingSummaryValidationError extends Schema.TaggedError<TrainingSummaryValidationError>()(
	"TrainingSummaryValidationError",
	{
		weeks: Schema.Number,
		message: Schema.String,
	},
) {}

export class TrainingSummaryDataError extends Schema.TaggedError<TrainingSummaryDataError>()(
	"TrainingSummaryDataError",
	{
		collection: Schema.String,
		message: Schema.String,
	},
) {}

