/**
 * The failure tags that survive the core boundary. `satisfies` keeps the
 * table complete at compile time: adding a member to `CoreToolError` without
 * listing its tag here is a type error, so the guard cannot drift from the
 * vocabulary the way the previous `instanceof` chain could.
 */
const CORE_TOOL_ERROR_TAGS = {
	ToolInputValidationError: true,
	ClientNotInitializedError: true,
	OperationUnavailableError: true,
	ApiError: true,
	NetworkError: true,
	NotFoundError: true,
	RateLimitError: true,
	ValidationError: true,
	EmptyMeasurementUpdateError: true,
	PaginationMismatchError: true,
	TemplatesSearchValidationError: true,
	TrainingSummaryDataError: true,
	TrainingSummaryValidationError: true,
	WorkoutPayloadError: true,
	WorkoutPrivacyError: true,
} as const satisfies Record<CoreToolTag, true>;

function isCoreToolError(error: RuntimeValue): error is CoreToolError {
	return (
		isObject(error) &&
		"_tag" in error &&
		isString(error._tag) &&
		Object.hasOwn(CORE_TOOL_ERROR_TAGS, error._tag)
	);
}

/**
 * Keep supported upstream tags typed at the core boundary. An operation is
 * external to core and its failure channel is intentionally unknown, so
	| "NetworkError"
	| "NotFoundError"
	| "RateLimitError"
	| "ValidationError"
	| "ToolInputValidationError"
	| "ClientNotInitializedError"
	| "OperationUnavailableError"
	| "WorkoutPrivacyError"
	| "WorkoutPayloadError"
	| "PaginationMismatchError"
	| "EmptyMeasurementUpdateError"
	| "TemplatesSearchValidationError"
	| "TrainingSummaryValidationError"
	| "TrainingSummaryDataError";

export const SAFE_DOMAIN_ERROR_TAGS: ReadonlySet<string> = Object.freeze(
	new Set<string>([
		"WorkoutPrivacyError",
		"WorkoutPayloadError",
		"PaginationMismatchError",
		"EmptyMeasurementUpdateError",
		"TemplatesSearchValidationError",
		"TrainingSummaryValidationError",
		"TrainingSummaryDataError",
		"ToolInputValidationError",
	]),
);
type TaggedValue = {
	readonly _tag?: ErrorTag;
	readonly path?: unknown;
};
}

const MAX_SAFE_USER_ERROR_LENGTH = 512;

/** Classify an error using bounded status, names, and supplied text. */
export function determineErrorType(error: RuntimeValue): ErrorType {
	const tag = taggedValue(error)?._tag;
	if (tag === "RateLimitError") return ErrorType.RATE_LIMIT;
	if (tag === "ValidationError") return ErrorType.VALIDATION_ERROR;
	if (tag === "NotFoundError") return ErrorType.NOT_FOUND;
	if (tag === "ApiError") return ErrorType.API_ERROR;
	if (tag === "NetworkError") return ErrorType.NETWORK_ERROR;
	if (tag === "ToolInputValidationError") return ErrorType.VALIDATION_ERROR;
	if (
		tag === "WorkoutPrivacyError" ||
		tag === "WorkoutPayloadError" ||
		tag === "EmptyMeasurementUpdateError" ||
		tag === "TemplatesSearchValidationError" ||
		tag === "TrainingSummaryValidationError"
	) {
		return ErrorType.VALIDATION_ERROR;
